import{_ as o,o as a,c as e,ai as n}from"./chunks/framework.BBSijY9B.js";const d=JSON.parse('{"title":"iPhone 侧边的操作按钮，现在一按就能和 Bot 语音对话","description":"","frontmatter":{"date":"2026-10-21T00:00:00.000Z","title":"iPhone 侧边的操作按钮，现在一按就能和 Bot 语音对话","summary":"官方 10 月 20 日（UTC+8）宣布 Grok Bot 可以绑定到 iPhone 操作按钮。30 秒设置步骤、没有操作按钮的机型怎么办，以及按下去之后最值得说的几句话。","category":"新闻简报","tags":["手机","语音","版本更新"],"sources":[{"url":"https://x.com/bot/status/2112252507762368684","author":"@bot","platform":"X"},{"url":"https://x.com/grok/status/2112558245940195748","author":"@grok（设置步骤回复）","platform":"X"},{"url":"https://apps.apple.com/us/app/grok-bot/id6794501026","author":"Grok Bot（App Store，1.16.0）","platform":"App Store"}],"updates":[{"link":"/faq/faq","title":"常见问题：语音一节补上 iPhone 操作按钮"}],"wordCount":737,"readingTime":2,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"iPhone 侧边的操作按钮，现在一按就能和 Bot 语音对话 | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"官方 10 月 20 日（UTC+8）宣布 Grok Bot 可以绑定到 iPhone 操作按钮。30 秒设置步骤、没有操作按钮的机型怎么办，以及按下去之后最值得说的几句话。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/daily/2026-10-21-iphone-action-button"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/daily-2026-10-21-iphone-action-button-11e8603d59.png"}],["meta",{"property":"og:image:alt","content":"iPhone 侧边的操作按钮，现在一按就能和 Bot 语音对话 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"iPhone 侧边的操作按钮，现在一按就能和 Bot 语音对话 | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"官方 10 月 20 日（UTC+8）宣布 Grok Bot 可以绑定到 iPhone 操作按钮。30 秒设置步骤、没有操作按钮的机型怎么办，以及按下去之后最值得说的几句话。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/daily-2026-10-21-iphone-action-button-11e8603d59.png"}],["meta",{"name":"twitter:image:alt","content":"iPhone 侧边的操作按钮，现在一按就能和 Bot 语音对话 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/daily/2026-10-21-iphone-action-button"}]]},"headers":[],"relativePath":"daily/2026-10-21-iphone-action-button.md","filePath":"daily/2026-10-21-iphone-action-button.md","lastUpdated":1792514041000}'),i={name:"daily/2026-10-21-iphone-action-button.md"};function r(s,t,p,l,h,c){return a(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="iphone-侧边的操作按钮-现在一按就能和-bot-语音对话" tabindex="-1">iPhone 侧边的操作按钮，现在一按就能和 Bot 语音对话 <a class="header-anchor" href="#iphone-侧边的操作按钮-现在一按就能和-bot-语音对话" aria-label="Permalink to &quot;iPhone 侧边的操作按钮，现在一按就能和 Bot 语音对话&quot;">​</a></h1><p>官方账号 <a href="https://x.com/bot/status/2112252507762368684" target="_blank" rel="noopener noreferrer">@bot</a> 在 10 月 20 日凌晨（UTC+8）发帖：<strong>Grok Bot 可以设成 iPhone 的操作按钮（Action Button），按一下就开始和 Bot 语音聊天</strong>。这条帖子一天内浏览量接近 190 万，是这两天 Grok Bot 讨论最多的话题。</p><p>它的意义不在&quot;又多一个入口&quot;：以前想交代一件事，要解锁、找 App、点语音；现在走路、开车、手里拿着东西时，<strong>按住侧键说一句话，事情就交出去了</strong>，Bot 在云电脑上做完再把结果放回对话里。</p><h2 id="_30-秒设置" tabindex="-1">30 秒设置 <a class="header-anchor" href="#_30-秒设置" aria-label="Permalink to &quot;30 秒设置&quot;">​</a></h2><div class="steps"><ol><li><strong>更新 Grok Bot App</strong>：App Store 上的 Grok Bot 1.16.0 于 10 月 18 日发布。注意要更新的是 <strong>Grok Bot</strong>，不是 Grok 聊天 App。更新后先打开一次。</li><li>打开 iPhone 的 <strong>设置 → 操作按钮</strong>，左右滑到 <strong>快捷指令</strong>。</li><li>点 <strong>选取快捷指令</strong>，搜索 &quot;Grok Bot&quot;，选 <strong>Start Voice Chat</strong>。</li><li>回到桌面，按住侧边的操作按钮试一下。</li></ol></div><p><strong>列表里搜不到 Grok Bot？</strong> 官方 @grok 账号的回复是：这个选项只有在 Grok Bot App 更新后才会出现。先确认版本，再把 App 打开一次。</p><p>操作按钮是 iPhone 15 Pro 及之后部分机型才有的硬件按钮。手机系统要求按官方文档是 iOS 18 及以上。</p><h2 id="没有操作按钮也能用" tabindex="-1">没有操作按钮也能用 <a class="header-anchor" href="#没有操作按钮也能用" aria-label="Permalink to &quot;没有操作按钮也能用&quot;">​</a></h2><p>只要你的快捷指令 App 里能搜到 Grok Bot 的 Start Voice Chat，下面两种系统自带的办法也能做到&quot;一下就叫出来&quot;：</p><ul><li><strong>轻点背面</strong>：设置 → 辅助功能 → 触控 → 轻点背面 → 选&quot;轻点两下&quot;，指定一个运行 Start Voice Chat 的快捷指令。</li><li><strong>嘿 Siri + 快捷指令名</strong>：在快捷指令 App 里新建一个快捷指令，只放 Start Voice Chat 这一个动作，名字起成好念的短词，比如&quot;叫 Bot&quot;。之后对 Siri 说这个名字就会运行它。</li></ul><p>已经把操作按钮给了手电筒、相机的，可以新建一个快捷指令，用&quot;从菜单中选取&quot;放两个选项（手电筒、Grok Bot 语音），再把操作按钮绑到这个快捷指令上。</p><h2 id="按下去之后-说什么最值" tabindex="-1">按下去之后，说什么最值 <a class="header-anchor" href="#按下去之后-说什么最值" aria-label="Permalink to &quot;按下去之后，说什么最值&quot;">​</a></h2><p>语音最适合<strong>交代</strong>，不适合<strong>审阅</strong>。按下按钮说完就放手，结果回到电脑上再看。几句可以直接说的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>记一下：明天上午十点前给李总回电话，问合同第三条改没改。到时间提醒我。</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我查一下这周六下午附近能订到的羽毛球场，列三个选项，先别下单。</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>刚才开会说的三件事：报价单周三前发、样品周五到、下周一复盘。整理成待办发我，别发给任何人。</span></span></code></pre></div><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><ul><li><strong>语音交代的事一样会走审批</strong>：发消息、下单、删除这类不可逆的动作，Bot 仍然会先出卡片等你点头，不会因为你是用语音说的就直接执行。</li><li>在车上用，请用免提和车载蓝牙，别低头看屏幕。</li><li>官方更新日志（0.71.2）写到：语音聊天断线后会自动重连、接着同一段对话，信号差的地方不用从头再说。</li></ul><p>延伸阅读：<a href="/faq/faq">常见问题 · 能用语音吗</a>。</p>',19)])])}const u=o(i,[["render",r]]);export{d as __pageData,u as default};
